import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { RouterModule } from '@angular/router';
import { MatIconModule } from '@angular/material/icon';
import { ScheduleModalService } from '../../services/schedule-modal.service';

@Component({
  selector: 'app-schecon-page-layout',
  standalone: true,
  imports: [CommonModule, RouterModule, MatIconModule],
  templateUrl: './schecon-page-layout.component.html',
  styleUrls: ['./schecon-page-layout.component.scss'],
})
export class ScheconPageLayoutComponent {
  @Input() pageTitle = '';
  @Input() pageSubtitle = '';
  @Input() candidateCount = 0;
  @Input() accentColor = '#ed9630';
  /** 後方互換: 親コンポーネントが独自処理したい場合用 (通常はサービス経由) */
  @Output() scheduleClick = new EventEmitter<void>();

  constructor(
    private location: Location,
    private scheduleModal: ScheduleModalService,
  ) {}

  goBack(): void {
    this.location.back();
  }

  /** 「予定調整をする」ボタン: グローバルモーダルを開き、親の scheduleClick も発火 */
  onScheduleButtonClick(): void {
    this.scheduleModal.open();
    this.scheduleClick.emit();
  }
}
